import styled from '@emotion/styled';

interface StyledMainContainerProps {
  $fullWidth?: boolean;
  $noPaddingX?: boolean;
}

export const StyledMainContainer = styled('div', {
  shouldForwardProp: (propName) =>
    !['$fullWidth', '$noPaddingX'].includes(propName),
})<StyledMainContainerProps>(({ $fullWidth, $noPaddingX }) => ({
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
  backgroundColor: '#F9F9F9',
  borderRadius: '16px',
  border: '1px solid rgba(20, 20, 20, 0.08)',
  padding: '24px',
  ...($fullWidth && { width: '100%' }),
  ...($noPaddingX && {
    paddingLeft: '0px',
    paddingRight: '0px',
  }),
}));

export const StyledContentCardHeader = styled.div({
  display: 'flex',
  justifyContent: 'flex-start',
  alignItems: 'center',
  gap: '8px',
});
